Json::Value Sessions::toJson() const
{
    Json::Value ret;
    if(getId())
    {
        ret["id"]=(Json::Int64)getValueOfId();
    }
    else
    {
        ret["id"]=Json::Value();
    }
    if(getUserId())
    {
        ret["user_id"]=getValueOfUserId();
    }
    else
    {
        ret["user_id"]=Json::Value();
    }
    if(getAutomatedServiceId())
    {
        ret["automated_service_id"]=getValueOfAutomatedServiceId();
    }
    else
    {
        ret["automated_service_id"]=Json::Value();
    }
    if(getToken())
    {
        ret["token"]=getValueOfToken();
    }
    else
    {
        ret["token"]=Json::Value();
    }
    if(getIp())
    {
        ret["ip"]=getValueOfIp();
    }
    else
    {
        ret["ip"]=Json::Value();
    }
    if(getCreatedAt())
    {
        ret["created_at"]=getCreatedAt()->toDbStringLocal();
    }
    else
    {
        ret["created_at"]=Json::Value();
    }
    if(getTerminatedAt())
    {
        ret["terminated_at"]=getTerminatedAt()->toDbStringLocal();
    }
    else
    {
        ret["terminated_at"]=Json::Value();
    }
    if(getTerminationReason())
    {
        ret["termination_reason"]=getValueOfTerminationReason();
    }
    else
    {
        ret["termination_reason"]=Json::Value();
    }
    return ret;
}

