bool Sessions::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("user_id"))
    {
        if(!validJsonOfField(1, "user_id", pJson["user_id"], err, true))
            return false;
    }
    if(pJson.isMember("automated_service_id"))
    {
        if(!validJsonOfField(2, "automated_service_id", pJson["automated_service_id"], err, true))
            return false;
    }
    if(pJson.isMember("token"))
    {
        if(!validJsonOfField(3, "token", pJson["token"], err, true))
            return false;
    }
    else
    {
        err="The token column cannot be null";
        return false;
    }
    if(pJson.isMember("ip"))
    {
        if(!validJsonOfField(4, "ip", pJson["ip"], err, true))
            return false;
    }
    else
    {
        err="The ip column cannot be null";
        return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(5, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("terminated_at"))
    {
        if(!validJsonOfField(6, "terminated_at", pJson["terminated_at"], err, true))
            return false;
    }
    if(pJson.isMember("termination_reason"))
    {
        if(!validJsonOfField(7, "termination_reason", pJson["termination_reason"], err, true))
            return false;
    }
    return true;
}
